base=Path(__file__).parent
def change(rows, id, **fields):
    for i,row in enumerate(rows):
        if row[0]==id:
            value=list(row)
            for index,text in fields.items(): value[int(index)]=text
            rows[i]=tuple(value)
            return
    raise ValueError(id)

